let reverse_in_place (d : 'a deque) : unit =
  let rec loop (no : 'a dqnode option) : unit =
    begin match no with
    | None -> ()
    | Some n ->
      let nxt = n.next in
      n.next <- n.prev;
      n.prev <- nxt;
      loop nxt
    end
  in
  loop d.head;
  let h = d.head in
  d.head <- d.tail;
  d.tail <- h

