public static int[][] rotate90(int[][] m) {
    if (m == null || m.length == 0 || m[0] == null) {
        return null;
    }
    int rows = m.length;
    int cols = m[0].length;
    for (int i = 0; i < rows; i++) {
        if (m[i] == null || m[i].length != cols) {
            return null;
        }
    }
    int[][] out = new int[cols][rows];
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            out[j][rows - 1 - i] = m[i][j];
        }
    }
    return out;
}
